package cn.huankan.stream;
import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.scheduling.annotation.Scheduled;
@Service public class QualificationAuditService {
 private final JdbcTemplate db;public QualificationAuditService(JdbcTemplate db){this.db=db;}
 public List<Map<String,Object>> recompute(long after,int limit,UUID subscription){if(after<0||limit<1||limit>100)throw new IllegalArgumentException("资格重算每批1至100条");Map<String,Object> client=subscription==null?null:db.queryForMap("SELECT * FROM stream_connection WHERE id=?",subscription);var rows=db.queryForList("SELECT q.*,clock_timestamp() qualification_evaluated_at,?::uuid subscription_id,COALESCE((SELECT CASE WHEN acknowledged_at IS NOT NULL THEN 'ACKNOWLEDGED' ELSE outcome END FROM stream_delivery d WHERE d.outbox_id=q.id ORDER BY sent_at DESC,id LIMIT 1),'NOT_DELIVERED') delivery_status FROM qualification_explanation q WHERE q.id>? ORDER BY q.id LIMIT ?",subscription,after,limit);for(var row:rows){row.put("evaluation_mode","READ_ONLY_RECOMPUTE");row.put("subscription_eligible",client==null?null:eligible(row,client));row.put("subscription_reason",client==null?"未指定订阅；这是只读重算，不产生通知":reason(row,client));}return rows;}
 private boolean eligible(Map<String,Object> row,Map<String,Object> c){return reason(row,c).equals("订阅条件符合；实际发送与确认以投递账本为准");}
 private String reason(Map<String,Object> r,Map<String,Object> c){if(((Number)r.get("id")).longValue()<=((Number)c.get("initial_cursor")).longValue())return "订阅游标已覆盖此位置";if(Objects.toString(r.get("rejection_reason"),"").startsWith("许可"))return "来源许可未允许当前展示";if(c.get("watch_owner_key")!=null&&!Boolean.TRUE.equals(db.queryForObject("SELECT watch_matches(?,?,?,?,?,?)",Boolean.class,c.get("watch_owner_key"),r.get("evidence_id"),r.get("event_id"),r.get("source_id"),r.get("source_level"),r.get("priority"))))return "未命中此用户真实关注规则";String scope=c.get("subscription_scope").toString();if(!scope.equals("HISTORY")&&r.get("notification_kind").equals("HISTORICAL_BACKFILL")&&!scope.equals("LEADS"))return "历史回填被订阅规则排除";if(!scope.equals("HISTORY")&&!Boolean.TRUE.equals(r.get("official_eligible"))&&!(scope.equals("LEADS")&&r.get("source_id").equals("GDELT")))return "来源等级或订阅范围不符合";try{var a=c.get("subscribed_sources");if(a instanceof java.sql.Array array){String[] selected=(String[])array.getArray();if(selected.length>0&&!Arrays.asList(selected).contains(r.get("source_id").toString()))return "不在关注来源列表";}}catch(java.sql.SQLException e){throw new IllegalStateException("订阅来源读取失败",e);}if(((Number)r.get("priority")).intValue()<((Number)c.get("minimum_priority")).intValue())return "未达到用户规则优先级；规则优先级不是事实核验";return "订阅条件符合；实际发送与确认以投递账本为准";}
 @Scheduled(fixedDelay=5000,initialDelay=5000) @Transactional public void auditNew(){long after=db.queryForObject("SELECT last_outbox FROM notification_audit_cursor WHERE name='LIVE_RULE_AUDIT' FOR UPDATE",Long.class);var rows=recompute(after,100,null);for(var r:rows)db.update("INSERT INTO notification_evaluation(outbox_id,event_id,source_id,event_type,source_level,qualification_rule_id,qualification_rule_version,qualified,rejection_reason,delivery_status,evaluation_mode) VALUES(?,?,?,?,?,?,?,?,?,?,'LIVE_RULE_AUDIT')",r.get("id"),r.get("event_id"),r.get("source_id"),r.get("event_type"),r.get("source_level"),r.get("qualification_rule_id"),r.get("qualification_rule_version"),r.get("qualified"),r.get("rejection_reason"),r.get("delivery_status"));if(!rows.isEmpty())db.update("UPDATE notification_audit_cursor SET last_outbox=? WHERE name='LIVE_RULE_AUDIT'",rows.getLast().get("id"));}
 public Object status(){return Map.of("reasons",db.queryForList("SELECT qualified,rejection_reason,count(*) records FROM qualification_explanation GROUP BY qualified,rejection_reason ORDER BY records DESC"),"trace_count",db.queryForObject("SELECT count(*) FROM notification_evaluation",Long.class),"qualification_positions",db.queryForObject("SELECT count(*) FROM notification_dispatch",Long.class),"delivery",db.queryForList("SELECT delivery_type,outcome,count(*) records,count(*) FILTER(WHERE acknowledged_at IS NOT NULL) acknowledgements FROM stream_delivery GROUP BY delivery_type,outcome"),"task_accounting",db.queryForList("SELECT source_id,task_status,commit_state,counter_state,count(*) tasks,sum(committed_raw_records) committed_records,sum(committed_history_versions) committed_history_versions FROM collection_task_accounting GROUP BY source_id,task_status,commit_state,counter_state ORDER BY source_id,task_status"));}
}
